/* api.c: the engine's routines for the game (step 8.5d). The game (task 0) calls them through __engcall (engcall.asm); the
 * table api_tab (generated by tools/mkgame.py into build/game/api_tab.c) maps the numbers of build/game/engine_names.txt to
 * the api_<Name> functions of this file; a name without a function here stops the program with its number in result word 30
 * (api_unimpl: MB_RESULT(30) = number, status 2). Entry 0 is the bank loader, called by __farcall.
 *
 * The arguments are on the shared stack exactly as the game's C compiler pushed them, so every api_ function has the
 * parameter types of the routine it stands for (or of its wrapper in src/game/engapi.c, which copies strings and results
 * through its own frame: a pointer into the game's native memory would mean nothing in task 1).
 * A picture is a handle: 1..NPIC, an index into pics[]; the game keeps it in its picture variables as the low word of a
 * farptr (0 = no picture). The pixels stay in the engine's blocks (gfx.c). */
#include "eng.h"
#include "mailbox.h"
#include "gamemap.h"

extern u8 banktab[64];
void eng_halt(void);

/* ---- the code banks */

#define POOL_N ((BANK_POOL_END - BANK_POOL_FIRST) / 2)
static u8 pool_bank[POOL_N];              /* the bank in pool entry k, 0 = free */
#define FC_TICK (*(volatile u8 *)0x90)         /* farcall.asm: the tick, and the tick at which the bank in a pool block was last used */
#define FC_STAMP ((volatile u8 *)(0x91 - BANK_POOL_FIRST))

/* Any bank can be taken for another one: a caller on the bank stack that finds its bank gone is brought back by the return
 * path of farcall.asm (@reload), so a chain of calls can nest more banks than the pool holds (docs/HEAP-STUDY.md section 6). The
 * bank being loaded is the one place no other bank may take. */

u16 api_bankload(u16 bank)
{
    DaxEntry e;
    u8 k, t, a, b;
    DBG(1, bank);
    k = 0;                                 /* a free entry first, else the bank used longest ago (the trampoline stamps the pool block of every bank it enters) */
    a = 0;
    for (t = 0; t < POOL_N; t++) {
        if (pool_bank[t] == 0) {
            k = t;
            break;
        }
        b = (u8)(FC_TICK - FC_STAMP[BANK_POOL_FIRST + 2 * t]);
        if (b >= a) {
            a = b;
            k = t;
        }
    }
    if (pool_bank[k])
        banktab[pool_bank[k] - 1] = 0;
    if (img_entry("BANK    ", (u8)bank, &e) != 0 || img_read_blocks(e.offset, e.raw, (u8)(BANK_POOL_FIRST + 2 * k)) != 0) {
        MB_RESULT(31) = bank;
        MB_RESULT(29) = 1;                 /* the bank is not in the image or cannot be read */
        MB_STATUS = MB_FAIL;
        eng_halt();
    }
    MB_RESULT(7) = (u16)bank;
    MB_RESULT(8) = e.raw;
    MB_RESULT(9) = (u16)(MB_RESULT(9) + 1);
    pool_bank[k] = (u8)bank;
    banktab[bank - 1] = (u8)(BANK_POOL_FIRST + 2 * k);
    return 0;
}

/* a routine of engine_names.txt that has no function here */
extern u8 eng_idx;
void api_unimpl(void)
{
    MB_RESULT(30) = eng_idx;
    MB_STATUS = MB_FAIL;
    eng_halt();
}

/* ---- pictures */

#define NPIC 128
#define H_DRAWBUF 0x7F01u                 /* DrawBuf, the staging buffer of gfx.c: not a Pic */
Pic pics[NPIC];
u8 pic_live[NPIC];

static u16 pic_new(void)
{
    u8 i;
    for (i = 0; i < NPIC; i++)
        if (!pic_live[i]) {
            pic_live[i] = 1;
            return (u16)(i + 1);
        }
    return 0;
}

static Pic *pic_of(u32 h)
{
    if (h == 0 || h > NPIC || !pic_live[(u8)h - 1])
        return 0;
    return &pics[(u8)h - 1];
}

/* The name of a picture file as a Pascal string -> 8 characters, upper case, space padded */
static void name8_of(const u8 *pas, char *out)
{
    u8 i, n = pas[0], c;
    for (i = 0; i < 8; i++) {
        c = i < n ? pas[1 + i] : ' ';
        if (c >= 'a' && c <= 'z')
            c = (u8)(c - 32);
        out[i] = (char)c;
    }
    out[8] = 0;
}

u16 api_LoadPicture(const u8 *name, u8 id, u8 flags, u8 color)
{
    char n8[9];
    DaxEntry e;
    Vol *v;
    u16 h;
    u8 st;
    name8_of(name, n8);
    st = vol_lookup(n8, id, &v, &e);
    DBG(6, ((u16)id << 4) | st);
    if (st != 0)
        return 0;
    h = pic_new();
    if (h == 0)
        return 0;
    st = pic_load_e(&pics[h - 1], &v->f, &e, color, (u8)(flags & 1));
    if (st != 0) {
        pic_live[h - 1] = 0;
        return 0;
    }
    return h;
}

u16 api_AllocatePicture(u16 height, u16 wcols, u8 items, u8 flags)
{
    u16 h;
    if (height == 0xA8 && wcols == 0x15)
        return H_DRAWBUF;
    h = pic_new();
    if (h == 0)
        return 0;
    if (pic_alloc(&pics[h - 1], (u8)height, (u8)wcols, items, (u8)(flags & 1)) != 0) {
        pic_live[h - 1] = 0;
        return 0;
    }
    return h;
}

void api_ReleasePicture(u16 h)
{
    Pic *p = pic_of(h);
    if (p) {
        pic_free(p);
        pic_live[h - 1] = 0;
    }
}

void api_ShowPicture(s16 col, s16 row, u32 buf)
{
    Pic *p = pic_of(buf);
    DBG(5, ((u16)(u8)col << 6) | ((u16)(u8)row << 1) | (p != 0));
    if (p && col >= 0 && row >= 0)
        gfx_item(p, 0, (u8)col, (u8)row);
}

void api_ShowPictureItem(s16 col, s16 row, u16 h, u8 item)
{
    Pic *p = pic_of(h);
    if (p && col >= 0 && row >= 0 && item < p->items)
        gfx_item(p, item, (u8)col, (u8)row);
}

void api_DrawPictureItem(s16 col, s16 row, u8 item, u8 flags, u32 src, u32 dst)
{
    Pic *p = pic_of(src);
    (void)dst;                             /* always DrawBuf */
    if (p && item < p->items)
        db_item(p, item, (u8)col, (u8)row, flags);
}

void api_DrawPictureItemClipped(s16 col, s16 row, u8 item, u8 flags, u32 src, u32 dst)
{
    Pic *p = pic_of(src);
    (void)dst;                             /* always DrawBuf */
    if (p && item < p->items)
        db_item_clip(p, item, col, row, flags, 0);
}

/* DrawIcon's blit (ovl32 04FC): the original copies the picture (mirrored for icon sets above 3) into a new one, draws that
 * and frees it; the copy is not observable, so the picture is drawn as it is. The game side (the patched DrawIcon) looks the
 * handle up in PictureSlots. */
void api_DrawIconPic(u16 h, s16 col, s16 row, u8 mirror)
{
    Pic *p = pic_of(h);
    if (p)
        db_item_clip(p, 0, col, row, 1, mirror);
}

/* CopyPictureSlot's copies of the editor (ovl16 nested) and MergePictureData (ovl17 032F) on the pictures of the icon */
void api_PictureCopy(u16 src, u16 dst)
{
    Pic *s = pic_of(src), *d = pic_of(dst);
    if (s && d)
        pic_combine(s, d, 0);
}

/* Load24x24Set (ovl32 0022): all the items of the loaded set, as a block of bytes, into the tile bank at item number `index` of the
 * set's own item size (the PC copies the tails of the two picture records with Move) */
void api_PictureAppend(u16 src, u16 dst, u8 index)
{
    Pic *s = pic_of(src), *d = pic_of(dst);
    if (s && d)
        pic_append(s, d, index);
}

void api_PictureItemCopy(u16 src, u16 dst, u8 item, u8 mirror)
{
    Pic *s = pic_of(src), *d = pic_of(dst);
    if (s && d)
        pic_item_copy(s, d, item, mirror);
}

void api_MergePictureData(u32 src, u32 dst)
{
    Pic *s = pic_of(src), *d = pic_of(dst);
    if (s && d)
        pic_combine(s, d, 1);
}

/* The save area of the image (the game's files: rtl_file.c keeps a directory in it): byte addressed, at most 128 bytes a call,
 * the buffer in the caller's frame (the shared stack). A failure stops the program with the code 0xF3. */
void api_SaveRead(u32 off, u8 *dst, u8 n)
{
    if ((u16)(off >> 8) >= img_save_sectors || img_read(((u32)img_save_lsn << 8) + off, dst, n) != 0) {
        MB_RESULT(30) = 0xF3;
        MB_RESULT(29) = (u16)off;
        MB_STATUS = MB_FAIL;
        eng_halt();
    }
}

void api_SaveWrite(u32 off, const u8 *src, u8 n)
{
    if ((u16)(off >> 8) >= img_save_sectors || img_write(((u32)img_save_lsn << 8) + off, src, n) != 0) {
        MB_RESULT(30) = 0xF4;
        MB_RESULT(29) = (u16)off;
        MB_STATUS = MB_FAIL;
        eng_halt();
    }
}

/* what LoadSpriteList and Show3DSprite (ovl28, game code) need of a picture record: its place on the screen, its size, its pixels */
void api_SetPictureXY(u16 h, u16 x, u16 y)
{
    Pic *p = pic_of(h);
    if (p) {
        p->x = x;
        p->y = y;
    }
}

u16 api_PictureBytes(u16 h)
{
    Pic *p = pic_of(h);
    return p ? p->bytesize : 0;
}

void api_PicData(u16 h, u16 rel, const u8 *buf, u8 n, u8 key)
{
    Pic *p = pic_of(h);
    if (p)
        pic_put(p, rel, buf, n, key);
}

void api_DrawSpritePic(u16 h)
{
    Pic *p = pic_of(h);
    if (p)
        db_item_clip(p, 0, (s16)(p->x + 2), (s16)(p->y + 2), 1, 0);
}

void api_FillPictureRect(s16 col, s16 row, u16 w, u16 h, u8 color, u32 palette, u32 target)
{
    (void)palette;
    (void)target;
    db_fill(col, row, w, h, color);
}

void api_FlushPictureChanges(void)
{
    db_flush();
}

/* RemapPictureColors (res07 0464:1F51): the colours of one item (FirstItem, item 0 when negative: the original's quirk) that
 * the map `from` names become the ones `to` names; the maps arrive copied to the wrapper's frame. Flicker (a random subset
 * of the pixels, doors only) needs the game's Random: not here yet. */
void api_RemapPictureColors(const u8 *from, const u8 *to, s16 first, u8 flicker, u16 h)
{
    u8 lut[16], c;
    Pic *p = pic_of(h);
    if (p == 0)
        return;
    if (flicker) {
        MB_RESULT(30) = 0xF1;
        MB_STATUS = MB_FAIL;
        eng_halt();
    }
    for (c = 0; c < 16; c++)
        lut[c] = c;
    for (c = 0; c < 16; c++)
        if (from[c] != to[c])
            lut[from[c] & 15] = (u8)(to[c] & 15);
    pic_remap(p, (u8)(first < 0 ? 0 : first), lut);
}

void api_SetPaletteRegister(u8 reg, u8 color)
{
    gfx_pal_reg(reg, color);
}

/* ---- DAX blocks and files: LoadDaxBlock and the Pascal file runtime of the game (src/game/engapi.c, rtl_sys.c) */

#define STAGE_BLK 0x0E                    /* two blocks: the unpacked block api_DaxLoad found */
static u16 stage_size;

/* The unpacked block `id` of the DAX file `name` (a Pascal string, no extension) into the stage; its size, 0 = not found */
u16 api_DaxLoad(const u8 *name, u16 id)
{
    char n8[9];
    DaxEntry e;
    Vol *v;
    u8 st;
    stage_size = 0;
    name8_of(name, n8);
    st = vol_lookup(n8, (u8)id, &v, &e);
    if (st != 0 || e.raw > 0x4000u)
        return 0;
    if (dax_unpack(&v->f, &e, 0, 0, STAGE_BLK, 0, 0) != 0)
        return 0;
    stage_size = e.raw;
    return stage_size;
}

/* n bytes (n <= 256) of the stage from `off` to dst (the caller's frame) */
void api_DaxRead(u16 off, u8 *dst, u16 n)
{
    u16 c;
    while (n > 0) {
        win_set(0, (u8)(STAGE_BLK + (off >> 13)));
        c = (u16)(0x2000u - (off & 0x1FFFu));
        if (c > n)
            c = n;
        k_copy(dst, WIN0 + (off & 0x1FFFu), (u8)c);
        dst += c;
        off += c;
        n -= c;
    }
}

/* 1 when a mounted volume holds the file `name` (Pascal string, no extension); a new disk in drive 1 is looked at too */
u16 api_FileKnown(const u8 *name)
{
    char n8[9];
    name8_of(name, n8);
    return vol_has(n8);
}

/* ---- video, text, fills */

static u8 video_up;

void api_SetVideoMode(u8 mode)
{
    (void)mode;
    if (!video_up) {
        gfx_init();
        db_init();
        video_up = 1;
    } else {
        gfx_clear(0);
        gfx_default_palette();
    }
}

void api_RestoreVideoMode(void)
{
    /* the game goes back to text mode to print an error and quit: note it for the harness; the message (rtl_file.c's console)
     * and the exit follow */
    MB_RESULT(27) = 0xE7;
}

void api_SetPageSegment(u8 page) { (void)page; }
void api_SetActivePage(u8 page) { (void)page; }
void api_SetEgaFillRegisters(void) { }

void api_FillPlaneRect(s8 l, s8 t, s8 r, s8 b, u8 page, u8 value)
{
    if (page == 0)
        gfx_fill_cells((u8)l, (u8)t, (u8)r, (u8)b, value);
}

void api_DrawGlyph(u8 col, u8 row, u8 color, u8 count, u8 glyph, u8 textset)
{
    gfx_glyph(col, row, color, count, glyph, textset);
}

void api_LoadGameFont(void)
{
    DaxEntry e;
    Vol *v;
    if (vol_lookup("8X8D1   ", 201, &v, &e) == 0)
        gfx_font_load_e(&v->f, &e);
}

